  "code": "def generated_builder(feature_cache, extra):\n    # Constants for thresholds and scaling, configurable via extra\n    gap_threshold = float(extra.get('gap_threshold', 0.2))\n    weight_scale = float(extra.get('weight_scale', 1.0))  # Scaling factor for weight sharpness\n    eps = 1e-6\n    objective = feature_cache['objective']\n    regret = feature_cache['regret']\n    # Build pair mask: pairs where objective difference exceeds threshold\n    mask = (objective[:, :, None] - objective[:, None, :]) > gap_threshold\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Initialize the pair weights as ones, then scale via hyperparameters\n    weight = torch.ones_like(b_idx, dtype=objective.dtype, device=objective.device)\n    # Optional: apply a soft scaling to weights based on gap magnitude\n    # Compute the gap for each pair\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Normalize gap to [0, 1] for smooth scaling\n    norm_gap = gap / (gap.abs().max() + eps)\n    # Use sigmoid to produce weights between 0 and 1, scaled by weight_scale\n    weight_factors = torch.sigmoid(norm_gap * weight_scale)\n    # Assign the scaled weights\n    weight = weight_factors\n    # Return PrefBatch with fixed pair indices and updated weights\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_regret_blend'})"
