  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    advantage = feature_cache['advantage']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'advantage_softmax'})\n    adv_diff = advantage[b_idx, loser_idx] - advantage[b_idx, winner_idx]\n    # stabilize by subtracting max per batch\n    batch_size = int(objective.shape[0])\n    max_adv = torch.full((batch_size,), float('-inf'), dtype=adv_diff.dtype, device=adv_diff.device)\n    max_adv.scatter_reduce_(0, b_idx, adv_diff, reduce='amax', include_self=True)\n    adv_diff_stable = adv_diff - max_adv[b_idx]\n    exp_adv = torch.exp(adv_diff_stable.clamp(min=-20.0, max=20.0))\n    # per-instance sums\n    sum_exp_adv = torch.zeros(batch_size, dtype=adv_diff.dtype, device=adv_diff.device)\n    counts = torch.bincount(b_idx.to(torch.int64), minlength=batch_size).to(dtype=adv_diff.dtype)\n    sum_exp_adv.index_add_(0, b_idx, exp_adv)\n    # avoid division by zero\n    norm_exp_adv = exp_adv / sum_exp_adv[b_idx].clamp_min(1e-8)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=norm_exp_adv, meta={'builder': 'all_pairs', 'weight_family': 'advantage_softmax'})\n"
}

